def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]

    if start_value == 0:
        return None

    change = end_value - start_value
    percent_change = (change / start_value) * 100

    return {
        "value": percent_change,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
